#!/bin/bash
set -e

# Generate Birdstar's native app icons from a single source PNG.
#
# Following Ditto's approach, the density-specific icon PNGs are treated as
# build artifacts: they are generated by this script and .gitignore'd rather
# than checked in. The script creates the mipmap density directories itself
# (git doesn't track empty dirs, so they're absent on a fresh checkout).
# Run this before building the APK.
#
# Source: public/birdstar.png — a finished, full-bleed 512x512 app-icon
# design (the constellation bird on a dark navy rounded square). Unlike
# Ditto, there is no monochrome SVG to recolor/composite: we simply resize
# the finished artwork into every density bucket.
#
# Requires ImageMagick (`magick` on v7, `convert` on v6).

GREEN='\033[0;32m'
YELLOW='\033[1;33m'
NC='\033[0m'

echo -e "${GREEN}Generating Birdstar app icons...${NC}\n"

# ImageMagick 7+ uses `magick`; ImageMagick 6 (Ubuntu/Debian) uses `convert`.
if command -v magick &> /dev/null; then
    MAGICK="magick"
elif command -v convert &> /dev/null; then
    MAGICK="convert"
else
    echo -e "${YELLOW}Error: ImageMagick not found. Install it to generate icons.${NC}"
    echo "On Fedora/RHEL: sudo dnf install ImageMagick"
    echo "On Ubuntu/Debian: sudo apt-get install imagemagick"
    exit 1
fi

SOURCE_PNG="public/birdstar.png"

if [ ! -f "$SOURCE_PNG" ]; then
    echo -e "${YELLOW}Error: Source icon not found at $SOURCE_PNG${NC}"
    exit 1
fi

# Adaptive-icon background shown behind the foreground when a launcher masks
# it into a circle/squircle — matches the artwork's dark navy so the crop is
# seamless. Also matches capacitor.config.ts backgroundColor and index.html
# theme-color.
BG_COLOR="#05070f"

# ── Legacy launcher icons (ic_launcher.png / ic_launcher_round.png) ──
# Used on pre-API-26 devices and as a fallback on some launchers. The source
# is already a finished square icon, so we just resize it to each density.

echo "Generating legacy launcher icons..."

make_legacy_square() {
    local size=$1
    local dest=$2
    $MAGICK "$SOURCE_PNG" -resize "${size}x${size}" "$dest"
}

# make_legacy_round: resized icon masked into a circle.
make_legacy_round() {
    local size=$1
    local dest=$2
    local mask="$TMPDIR/circle_mask_${size}.png"
    $MAGICK -size "${size}x${size}" "xc:none" \
        -fill white -draw "circle $((size/2)),$((size/2)) $((size/2)),0" \
        "$mask"
    $MAGICK \( "$SOURCE_PNG" -resize "${size}x${size}" \) \
        "$mask" -compose dst-in -composite \
        "$dest"
}

TMPDIR=$(mktemp -d)
trap 'rm -rf "$TMPDIR"' EXIT

# The generated PNGs are gitignored, so on a fresh checkout (e.g. CI) the
# density directories don't exist — git can't track empty dirs and `cap sync`
# doesn't recreate them. ImageMagick won't create parent dirs when writing.
for density in mdpi hdpi xhdpi xxhdpi xxxhdpi; do
    mkdir -p "android/app/src/main/res/mipmap-${density}"
done

make_legacy_square 48  android/app/src/main/res/mipmap-mdpi/ic_launcher.png
make_legacy_square 72  android/app/src/main/res/mipmap-hdpi/ic_launcher.png
make_legacy_square 96  android/app/src/main/res/mipmap-xhdpi/ic_launcher.png
make_legacy_square 144 android/app/src/main/res/mipmap-xxhdpi/ic_launcher.png
make_legacy_square 192 android/app/src/main/res/mipmap-xxxhdpi/ic_launcher.png

make_legacy_round 48  android/app/src/main/res/mipmap-mdpi/ic_launcher_round.png
make_legacy_round 72  android/app/src/main/res/mipmap-hdpi/ic_launcher_round.png
make_legacy_round 96  android/app/src/main/res/mipmap-xhdpi/ic_launcher_round.png
make_legacy_round 144 android/app/src/main/res/mipmap-xxhdpi/ic_launcher_round.png
make_legacy_round 192 android/app/src/main/res/mipmap-xxxhdpi/ic_launcher_round.png

# ── Adaptive icon foreground PNGs (API 26+) ──
# The launcher masks the 108dp canvas down to the inner 72dp "safe zone", so
# the artwork must be inset. We place the full square design at ~66% of the
# canvas on a transparent background; the adaptive <background> color shows
# through the masked corners.

echo "Generating adaptive foreground PNGs..."

make_foreground() {
    local size=$1
    local content_size=$(echo "$size * 66 / 100" | bc)
    local dest=$2
    $MAGICK -size "${size}x${size}" "xc:none" \
        \( "$SOURCE_PNG" -resize "${content_size}x${content_size}" \) \
        -gravity center -compose over -composite \
        "$dest"
}

make_foreground 108 android/app/src/main/res/mipmap-mdpi/ic_launcher_foreground.png
make_foreground 162 android/app/src/main/res/mipmap-hdpi/ic_launcher_foreground.png
make_foreground 216 android/app/src/main/res/mipmap-xhdpi/ic_launcher_foreground.png
make_foreground 324 android/app/src/main/res/mipmap-xxhdpi/ic_launcher_foreground.png
make_foreground 432 android/app/src/main/res/mipmap-xxxhdpi/ic_launcher_foreground.png

# Adaptive background color. Overwrites the Capacitor template's teal grid so
# the masked corners read as navy, matching the artwork.
BACKGROUND_COLOR_FILE="android/app/src/main/res/values/ic_launcher_background.xml"
mkdir -p android/app/src/main/res/values
cat > "$BACKGROUND_COLOR_FILE" << EOF
<?xml version="1.0" encoding="utf-8"?>
<resources>
    <color name="ic_launcher_background">${BG_COLOR}</color>
</resources>
EOF

# The Capacitor template also ships a vector foreground referenced from
# drawable-v24/. Point the adaptive icon at our PNG foreground + color
# background instead so the density PNGs above are actually used.
for f in \
    android/app/src/main/res/mipmap-anydpi-v26/ic_launcher.xml \
    android/app/src/main/res/mipmap-anydpi-v26/ic_launcher_round.xml; do
    if [ -f "$f" ]; then
        cat > "$f" << 'EOF'
<?xml version="1.0" encoding="utf-8"?>
<adaptive-icon xmlns:android="http://schemas.android.com/apk/res/android">
    <background android:drawable="@color/ic_launcher_background"/>
    <foreground android:drawable="@mipmap/ic_launcher_foreground"/>
</adaptive-icon>
EOF
    fi
done

# ── iOS App Icon (1024x1024) ──

echo "Generating iOS app icon..."

IOS_ICON_DIR="ios/App/App/Assets.xcassets/AppIcon.appiconset"
if [ -d "$IOS_ICON_DIR" ]; then
    IOS_ICON="$IOS_ICON_DIR/AppIcon-512@2x.png"
    # App Store icons must be fully opaque (no alpha). Flatten onto navy.
    $MAGICK "$SOURCE_PNG" -resize "1024x1024" \
        -background "$BG_COLOR" -alpha remove -alpha off \
        "$IOS_ICON"
    echo -e "  ${GREEN}✓${NC} $IOS_ICON"
else
    echo -e "  ${YELLOW}Skipped: $IOS_ICON_DIR not found${NC}"
fi

echo -e "\n${GREEN}App icons generated successfully from ${SOURCE_PNG}.${NC}"
